from lib import *
B = dict(mcq_b=3, text_b=4, match_b=3)
def lv(i,n): return "B1.1" if i < n//2 else "B1.2"
def mk(name, why_order, why_bank, why_text, why_mcq):
    return Topic(name, **B, order=why_order, bank=why_bank, gap=why_bank, text=why_text, mcq=why_mcq, match=why_bank)
